    44	     * This method is used to convert the json to Object
    45	     * 
    46	     * @param jsonString
    47	     * @return Object
    48	     */
    49	    public static Object convertJsonToObject( String jsonString, Class className ) throws JWSSignatureException
    50	    {
    51	        try
    52	        {
    53	            if( NullEmptyUtils.isNullorEmpty(jsonString) )
    54	                return new Object();
    55	
    56	            ObjectMapper objectMapper = new ObjectMapper().configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES,
    57	                    false);
    58	            objectMapper.enable(MapperFeature.ACCEPT_CASE_INSENSITIVE_ENUMS);
    59	
    60	            return objectMapper.readValue(jsonString, className);
    61	        }
    62	        catch( JsonParseException e )
    63	        {
    64	            log.error("Invalid a json String : " + jsonString);
    65	            return jsonString;
    66	        }
    67	        catch( JsonProcessingException e )
    68	        {
    69	            log.error("Error while converting string To Object " + jsonString, e);
    70	            throw new JWSSignatureException(e);
