151	    /**
152	     *
153	     * @param token
154	     * @return All claims from the token
155	     */
156	
157	    private Claims getAllClaimsFromToken( String token )
158	    {
159	        return Jwts.parser().setSigningKey(DatatypeConverter.parseBase64Binary(jwtConfig.getSecret()))
160	                .parseClaimsJws(token).getBody();
161	    }
162	
163	    /**
164	     *
165	     * @param token
166	     * @return Checks whether the token is expired or not
167	     */
168	    private Boolean isTokenExpired( String token )
169	    {
170	        final Date expiration = getExpirationDateFromToken(token);
171	        return expiration.before(new Date());
172	    }
