174	    /**
175	     *
176	     * @param user
177	     * @return Generates token with HS512 algorithm
178	     */
179	
180	    public String generateToken( CustomUser user )
181	    {
182	        Map<String, Object> claims = new HashMap<>();
183	        claims.put("username", user.getFiuId());
184	        claims.put(jwtConfig.getFiuId(), user.getUsername());
185	        claims.put("scope", "login");
186	        claims.put("type", "user");
187	        claims.put("creation", LocalDateTime.now());
188	        return doGenerateToken(claims, user.getUsername());
189	    }
