193	     * @param claims
194	     * @param subject
195	     * @return String token
196	     */
197	
198	    private String doGenerateToken( Map<String, Object> claims, String subject )
199	    {
200	        return Jwts.builder().setClaims(claims).setSubject(subject).setIssuedAt(new Date(System.currentTimeMillis()))
201	                .setExpiration(new Date(System.currentTimeMillis() + jwtConfig.getExpiration() * 1000))
202	                .signWith(SignatureAlgorithm.HS512, DatatypeConverter.parseBase64Binary(jwtConfig.getSecret()))
203	                .compact();
204	    }
