     *
     * @param signedConsent
     * @return
     */
    private ConsentDetailFromArtifact getConsentDetail( String signedConsent, String entityId, String txnId ) throws InvalidRequestException {
        try
        {

            if( NullEmptyUtils.isNullorEmpty(signedConsent) )
            {
                throw new InvalidRequestException(txnId, GeneralConstants.BAD_REQUEST, "signed consent is empty from consent id",
                        HttpStatus.BAD_REQUEST);
            }

            AACrEntityCollection aaCrEntityCollection = aaCrEntityRepository.findByEntityId(entityId);
            String certificateJson = JsonUtil.convertObjectToJson(aaCrEntityCollection.getEntityinfo().getCertificate());
            SignatureEntity.Keys[] keys = {(SignatureEntity.Keys) JsonUtil.convertJsonToObject(certificateJson, SignatureEntity.Keys.class)};
            SignatureEntity signatureEntity = new SignatureEntity(keys);

            signatureService.signatureVerification(new Verification(
                    new String(getUrlDecoder().decode(signedConsent.split("\\.")[1]), StandardCharsets.UTF_8),
                    signedConsent, signatureEntity));

            return (ConsentDetailFromArtifact) Base64Decoder.getDecodedObject(signedConsent.split("\\.")[1],
                    ConsentDetailFromArtifact.class);

        }
        catch( Exception e )
        {
            log.error("error in get consent detail:: signed consent= " + signedConsent, e);
            throw new InvalidRequestException(e);
        }

    }

